                          >
                            Up
                          </button>
                          <button
                            type="button"
                            onClick={() => moveNavItem(idx, 1)}
                            disabled={isLast}
                            className="h-8 rounded-full border border-zinc-200 bg-white px-3 text-xs font-medium text-zinc-900 hover:bg-zinc-100 disabled:opacity-50 dark:border-zinc-800 dark:bg-zinc-950 dark:text-zinc-50 dark:hover:bg-zinc-900"
