            <span className="font-mono">.env.local</span> and run{" "}
            <span className="font-mono">npm run convex:dev</span>.
          </p>
          <div className="mt-6">
            <Link className="text-sm font-medium underline" href="/">
              Back home
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return <CmsHomeWithConvex />;
