function firstNavbarHref(navbar: NavbarDoc | null, pagesById: Map<string, PageDoc>) {
  const items = (navbar?.items ?? []) as NavbarDoc["items"];
  for (const it of items) {
    if (it.type === "link") {
      const href = it.url?.trim();
      if (href) return href;
      continue;
    }
    const p = pagesById.get(it.pageId);
    if (p) return `/${p.slug}`;
  }
  return null;
}

