import { v } from "convex/values";

function nowMs() {
  return Date.now();
}

const navbarItem = v.union(
  v.object({
    type: v.literal("page"),
    pageId: v.id("pages"),
  }),
  v.object({
    type: v.literal("link"),
    label: v.string(),
    url: v.string(),
  }),
);

export const get = queryGeneric({
  args: { key: v.optional(v.string()) },
  handler: async (ctx, args) => {
