    return await ctx.db
      .query("navbars")
      .withIndex("by_key", (q) => q.eq("key", key))
      .unique();
  },
});

export const setItems = mutationGeneric({
  args: { key: v.optional(v.string()), items: v.array(navbarItem) },
  handler: async (ctx, args) => {
    const key = args.key ?? "main";
    const ts = nowMs();

    const existing = await ctx.db
      .query("navbars")
      .withIndex("by_key", (q) => q.eq("key", key))
      .unique();

    if (!existing) {
      return await ctx.db.insert("navbars", {
        key,
        items: args.items,
        createdAt: ts,
        updatedAt: ts,
      });
    }

    await ctx.db.patch(existing._id, { items: args.items, updatedAt: ts });
    return existing._id;
  },
});

