      <main className="mx-auto flex w-full max-w-3xl flex-col gap-10 px-6 py-16">
        <header className="flex flex-col gap-3">
          <h1 className="text-3xl font-semibold tracking-tight">repo934</h1>
          <p className="text-base leading-7 text-zinc-600 dark:text-zinc-400">
            Minimal CMS starter powered by Next.js + Convex.
          </p>
        </header>

        <section className="flex flex-col gap-3 rounded-2xl border border-zinc-200 bg-white p-5 dark:border-zinc-800 dark:bg-zinc-950">
          <div className="flex items-center justify-between gap-4">
            <div className="min-w-0">
              <div className="text-sm font-medium">Published pages</div>
              <div className="text-sm text-zinc-600 dark:text-zinc-400">
                {`${pages.length} live`}
              </div>
            </div>
            <Link
              href="/cms"
              className="inline-flex h-10 shrink-0 items-center justify-center rounded-full bg-zinc-900 px-4 text-sm font-medium text-white hover:bg-zinc-700 dark:bg-zinc-50 dark:text-black dark:hover:bg-zinc-200"
            >
              Open CMS
            </Link>
          </div>

          <div className="mt-2 divide-y divide-zinc-200 dark:divide-zinc-800">
            {(pages ?? []).map((p) => (
              <div key={p._id} className="flex items-center justify-between gap-4 py-3">
                <div className="min-w-0">
                  <div className="truncate text-sm font-medium">{p.title}</div>
                  <div className="truncate text-xs text-zinc-600 dark:text-zinc-400">
                    /{p.slug}
