                    onClick={async () => {
                      if (!confirm(`Delete "${p.title}"?`)) return;
                      await remove({ id: p._id });
                    }}
                  >
                    Delete
                  </button>
                </div>
              </div>
            ))}
            {pages && pages.length === 0 ? (
              <div className="py-6 text-sm text-zinc-600 dark:text-zinc-400">
                No pages yet.
              </div>
