                  ? ""
                  : navIsSaving
                    ? "Saving…"
                    : navDirty
                      ? "Unsaved changes (auto-saving)"
                      : "Saved"}
              </div>
              <div className="text-xs text-zinc-600 dark:text-zinc-400">Auto-saves</div>
            </div>
          </div>
        </section>
