function nowMs() {
  return Date.now();
}

const navbarItem = v.union(
  v.object({
    type: v.literal("page"),
    pageId: v.id("pages"),
  }),
  v.object({
    type: v.literal("link"),
    label: v.string(),
    url: v.string(),
  }),
);

export const get = queryGeneric({
  args: { key: v.optional(v.string()) },
  handler: async (ctx, args) => {
    const key = args.key ?? "main";
    return await ctx.db
      .query("navbars")
      .withIndex("by_key", (q) => q.eq("key", key))
      .unique();
  },
});

export const setItems = mutationGeneric({
  args: { key: v.optional(v.string()), items: v.array(navbarItem) },
  handler: async (ctx, args) => {
    const key = args.key ?? "main";
    const ts = nowMs();

    const existing = await ctx.db
      .query("navbars")
      .withIndex("by_key", (q) => q.eq("key", key))
      .unique();

    if (!existing) {
      return await ctx.db.insert("navbars", {
        key,
        items: args.items,
        createdAt: ts,
        updatedAt: ts,
      });
    }

    await ctx.db.patch(existing._id, { items: args.items, updatedAt: ts });
    return existing._id;
  },
});

